  "ch2-data-p2": "Если модель училась только на ночных фото, ей может быть трудно узнать предмет днём. Важно проверять качество и разнообразие данных.",
  "ch2-data-p3": "Поэтому данные сначала собирают, проверяют и приводят в порядок.",

