  "edu9-s3-desc": "숫자·벡터로 표현하여 예측이나 생성 수행",
  "edu10-lead": "STT는 말을 글로 바꾸고, TTS는 글을 소리로 읽어 줘요. 이번 주에는 마이크에 들어온 소리가 문자로 바뀌는 과정을 살펴봐요.",
  "edu10-deep": "마이크에 들어온 소리는 시간에 따라 달라지는 신호예요. STT는 그 신호의 특징을 분석하고 어떤 말을 했는지 추정해요.",
  "edu10-example": "휴대전화에 '내일 아홉 시에 알람 맞춰 줘'라고 말하면 음성 인식이 문장으로 바꾸고, 앱이 시간을 찾아 알람을 설정할 수 있어요.",
  "edu10-caution": "시끄럽거나 발음이 낯설면 말이 잘못 적힐 수 있어요. 이름과 숫자는 다시 확인하는 게 좋아요.",
  "edu10-flow": "음성이 글자가 되는 과정",
  "edu10-caption": "실제 음성 모델의 내부 처리 방식은 시스템마다 다릅니다. TTS는 반대로 텍스트를 입력받아 음성을 생성해요.",
  "edu10-question": "마이크에 말한 내용을 문자로 표시하는 기술은?",
