  "edu10-s3-desc": "말한 내용을 텍스트로 추정",
  "edu11-lead": "컴퓨터는 사진을 색과 밝기를 나타내는 숫자로 다뤄요. 픽셀과 RGB를 배우면 사진 인식의 첫 단계를 이해할 수 있어요.",
  "edu11-deep": "컬러 사진에서는 픽셀 하나를 보통 빨강·초록·파랑 숫자 세 개로 표현해요. 예를 들어 (255, 0, 0)은 빨간색이에요.",
  "edu11-example": "사진을 크게 확대하면 작은 점들이 보여요. 색을 빼거나 경계선을 찾으면 사진의 다른 특징이 드러나요.",
